/* ============================================================
   City Time Machine — cozy companion UI
   ============================================================ */

:root {
  --bg-top: #141026;
  --bg-bottom: #241a33;
  --ink: #f4ead8;
  --ink-dim: #b7a9c6;
  --amber: #ffcf87;
  --amber-soft: rgba(255, 207, 135, 0.16);
  --glass: rgba(22, 16, 34, 0.62);
  --glass-edge: rgba(255, 220, 170, 0.22);
}

* { margin: 0; padding: 0; box-sizing: border-box; }

html, body {
  height: 100%;
  overflow: hidden;
  background: radial-gradient(120% 90% at 50% 0%, var(--bg-top), var(--bg-bottom));
  color: var(--ink);
  font-family: "Avenir Next", "Segoe UI", "Trebuchet MS", system-ui, sans-serif;
  -webkit-font-smoothing: antialiased;
}

#stage {
  position: fixed;
  inset: 0;
}

#stage canvas {
  display: block;
  width: 100%;
  height: 100%;
  cursor: grab;
}
#stage canvas:active { cursor: grabbing; }

/* soft vignette + top glow for a "diorama in a lamp" feel */
body::before {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(90% 60% at 50% -10%, rgba(120, 90, 160, 0.28), transparent 60%),
    radial-gradient(140% 120% at 50% 55%, transparent 55%, rgba(6, 4, 12, 0.55) 100%);
  z-index: 2;
}

/* ---------- header ---------- */
#hud {
  position: fixed;
  top: 22px;
  left: 26px;
  z-index: 5;
  pointer-events: none;
  user-select: none;
}

#hud h1 {
  font-size: 21px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--ink);
  text-shadow: 0 2px 18px rgba(255, 190, 110, 0.35);
}
#hud h1::before {
  content: "◐ ";
  color: var(--amber);
}

#hud p {
  margin-top: 6px;
  font-size: 13px;
  color: var(--ink-dim);
  letter-spacing: 0.02em;
}

#hud .hint {
  display: block;
  margin-top: 3px;
  font-size: 11px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: rgba(183, 169, 198, 0.65);
}

/* ---------- control dock ---------- */
#dock {
  position: fixed;
  left: 50%;
  bottom: 26px;
  transform: translateX(-50%);
  display: flex;
  gap: 10px;
  z-index: 5;
}

#dock button {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 16px;
  border: 1px solid var(--glass-edge);
  border-radius: 999px;
  background: var(--glass);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  color: var(--ink);
  font: inherit;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  cursor: pointer;
  transition: border-color 0.25s, background 0.25s, transform 0.15s, box-shadow 0.25s;
  box-shadow: 0 8px 26px rgba(5, 3, 12, 0.45);
}

#dock button:hover {
  border-color: rgba(255, 220, 170, 0.5);
  background: rgba(38, 28, 54, 0.72);
  transform: translateY(-2px);
}

#dock button:active { transform: translateY(0); }

#dock .dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #5a4c70;
  transition: background 0.25s, box-shadow 0.25s;
}

#dock button[aria-pressed="true"] .dot {
  background: var(--amber);
  box-shadow: 0 0 10px 2px rgba(255, 207, 135, 0.55);
}

/* ---------- first-visit nudge ---------- */
#nudge {
  position: fixed;
  inset: 0;
  display: grid;
  place-items: center;
  z-index: 9;
  background: rgba(10, 7, 18, 0.35);
  backdrop-filter: blur(2px);
  -webkit-backdrop-filter: blur(2px);
  cursor: pointer;
  animation: breathe 2.4s ease-in-out infinite;
}

#nudge p {
  font-size: 14px;
  letter-spacing: 0.3em;
  text-transform: uppercase;
  color: var(--ink);
  padding: 16px 30px;
  border: 1px solid var(--glass-edge);
  border-radius: 999px;
  background: var(--glass);
}

@keyframes breathe {
  0%, 100% { opacity: 0.75; }
  50% { opacity: 1; }
}

@media (max-width: 560px) {
  #hud { top: 16px; left: 18px; }
  #hud h1 { font-size: 16px; }
  #hud p { font-size: 11px; }
  #dock { gap: 6px; bottom: 18px; }
  #dock button { padding: 9px 12px; font-size: 10px; }
}

/* ============================================================
   City Time Machine — a cozy 3D diorama of one city block.
   Always 9 PM. Windows glow, cars loop, tiny people stroll,
   a lo-fi tape hums in the background.

   Sections:
     0. globals & helpers
     1. renderer / scene / camera / controls
     2. palette & canvas-texture helpers
     3. ground: base island, streets, sidewalks, plaza
     4. buildings: facades, roofs, awnings, signs, neon
     5. street furniture: lamps, trees, benches, crosswalks
     6. vehicles
     7. pedestrians
     8. ambience: stars, moon, string lights, birds
     9. lo-fi soundtrack (Web Audio, generative 16-bar loop)
    10. UI wiring
    11. animation loop + self-test
   ============================================================ */
'use strict';

/* ---------------- 0. globals & helpers ---------------- */

const TAU = Math.PI * 2;
const rand  = (a, b) => a + Math.random() * (b - a);
const randi = (a, b) => Math.floor(rand(a, b + 1));
const pick  = (arr) => arr[Math.floor(Math.random() * arr.length)];
const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
const lerp  = (a, b, t) => a + (b - a) * t;

// World layout (top view, +x east, +z south):
//   streets: vertical at x = -16.5 / 0 / 16.5   (width 9, lane half-offset 2.4)
//   streets: horizontal at z = -16.5 / 0 / 16.5
//   blocks: 21 x 21 between streets; central block is the plaza.
const BLOCK = 21;
const STREET = 9;
const LANE = 2.4;          // lane center offset from street centerline
const V_STREETS = [-16.5, 0, 16.5];
const H_STREETS = [-16.5, 0, 16.5];

const state = {
  t: 0,                    // world clock (seconds), steppable
  step: 0.016,             // fixed step used by the self-test
  paused: false,
  soundOn: true,           // user preference; audio starts after a gesture
  audioStarted: false,
  autoSpin: true,
  cars: [],                // { group, speed, axis, dir, pos, loop }
  people: [],              // { group, path, t, speed, bobPhase }
  birds: [],               // { group, r, speed, phase, height }
  twinkle: [],             // star sprites { sprite, phase, speed }
  lampFlicker: [],         // { light, base, phase }
  signFlicker: [],         // { mat, base, phase, type }
};

// Shared materials & textures (created in section 1/2)
let renderer, scene, camera, controls;
let MAT = {};              // shared materials
let TEX = {};              // shared canvas textures

// Diagnostics exposed for the in-page self-test
window.__city = {
  state,
  step(dt) { state.t += dt; updateWorld(state.t, dt); },
  snapshot() {
    return {
      t: state.t,
      cars: state.cars.length,
      people: state.people.length,
      birds: state.birds.length,
      lamps: state.lampFlicker.length,
      signs: state.signFlicker.length,
      audio: {
        started: state.audioStarted,
        on: state.soundOn,
        time: audio ? audio.ctx.currentTime : 0,
        playing: !!(audio && audio.ctx && audio.ctx.state === 'running'),
      },
      camera: { pos: camera.position.toArray(), target: controls.target.toArray() },
    };
  },
};

/* ---------------- 1. renderer / scene / camera / controls ---------------- */

function initRenderer() { /* TODO */ }
function initLights()    { /* TODO */ }
function initSky()       { /* TODO */ }

/* ---------------- 2. palette & canvas-texture helpers ---------------- */

function makeCanvas(w, h) { /* TODO */ }
