/* ---------------- 11. animation loop ---------------- */

function updateWorld(t, dt) {
  updateCars(dt);
  updatePeople(dt);
  updateAmbience(t, dt);
}

let lastTime = 0;

function animate(now) {
  requestAnimationFrame(animate);
  const t = now * 0.001;
  const dt = Math.min(t - (lastTime || t), 0.05);
  lastTime = t;
  if (!state.paused) {
    state.t += dt;
    updateWorld(state.t, dt);
  }
  controls.update();
  renderer.render(scene, camera);
}

function boot() {
  initRenderer();
  buildMaterials();
  initLights();
  initSky();
  buildGround();
  buildCity();
  buildLamps();
  buildTrees();
  buildFountain();
  buildBirds();
  wireUI();
  requestAnimationFrame(animate);
}

