/* ---------------- 3. ground: base island, streets, sidewalks, plaza ---------------- */

// World layout: 9 blocks in a 3x3 grid (central one is the plaza).
const V_STREETS = [-15, 0, 15];   // street centerlines (x = const)
const H_STREETS = [-15, 0, 15];   // street centerlines (z = const)
const WORLD = 40.5;               // outer edge of the outermost blocks

function buildStreetTexture() {
  const S = 2048;                 // px for the full 91x91 ground
  const px = (u) => (u + 45.5) * (S / 91);

  return canvasTexture(S, S, (c) => {
    // --- sidewalks everywhere first ---
    c.fillStyle = '#57525f';
    c.fillRect(0, 0, S, S);
    // speckle
    for (let i = 0; i < 9000; i++) {
      const x = Math.random() * S, y = Math.random() * S;
      c.fillStyle = Math.random() < 0.5 ? 'rgba(255,255,255,0.035)' : 'rgba(0,0,0,0.05)';
      c.fillRect(x, y, 2, 2);
    }

    // --- asphalt strips ---
    const asphalt = () => {
      c.fillStyle = '#2f2d38';
    };
    for (const x of V_STREETS) {
      c.fillStyle = '#2f2d38';
      c.fillRect(px(x - 4.5), px(-45.5), 9 * S / 91, S);
      c.fillStyle = '#2f2d38';
      c.fillRect(0, px(x - 4.5), S, 9 * S / 91);
    }
    for (const z of H_STREETS) {
      c.fillStyle = '#2f2d38';
      c.fillRect(0, px(z - 4.5), S, 9 * S / 91);
      c.fillStyle = '#2f2d38';
      c.fillRect(px(z - 4.5), 0, 9 * S / 91, S);
    }
    // asphalt speckle
    for (let i = 0; i < 7000; i++) {
      const x = Math.random() * S, y = Math.random() * S;
      c.fillStyle = Math.random() < 0.5 ? 'rgba(255,255,255,0.03)' : 'rgba(0,0,0,0.06)';
      c.fillRect(x, y, 2, 2);
    }

    // --- curbs (block edges) ---
    c.strokeStyle = '#1f1d26';
    c.lineWidth = S / 91 * 0.35;
    for (let bx = -1; bx <= 1; bx++) {
      for (let bz = -1; bz <= 1; bz++) {
        if (bx === 0 && bz === 0) continue; // plaza handled separately
        const x0 = bx * 21 - 10.5, z0 = bz * 21 - 10.5;
        c.strokeRect(px(x0), px(z0), 21 * S / 91, 21 * S / 91);
      }
    }

    // --- center dashed lane lines ---
    c.strokeStyle = '#c9a35e';
    c.lineWidth = S / 91 * 0.22;
    c.setLineDash([S / 91 * 2.2, S / 91 * 2.4]);
    for (const x of V_STREETS) {
      c.beginPath();
      c.moveTo(px(x), px(-45.5));
      c.lineTo(px(x), px(45.5));
      c.stroke();
    }
    for (const z of H_STREETS) {
      c.beginPath();
      c.moveTo(px(-45.5), px(z));
      c.lineTo(px(45.5), px(z));
      c.stroke();
    }
    c.setLineDash([]);

    // --- crosswalks at every intersection approach ---
    const stripe = (x0, z0, horiz) => {
      c.save();
      c.translate(px(x0), px(z0));
      if (horiz) c.rotate(Math.PI / 2);
      const n = 7, gap = S / 91 * 0.55, len = S / 91 * 3.1;
      const total = n * gap * 2 - gap;
      c.fillStyle = 'rgba(235, 230, 220, 0.85)';
      for (let i = 0; i < n; i++) {
        c.fillRect(-total / 2 + i * gap * 2, -len / 2, gap, len);
      }
      c.restore();
    };
    for (const x of V_STREETS) {
      for (const z of H_STREETS) {
        // approaches along the vertical street (stripes run along x)
        stripe(x, z - 6.2, false);
        stripe(x, z + 6.2, false);
        // approaches along the horizontal street
        stripe(x - 6.2, z, true);
        stripe(x + 6.2, z, true);
      }
    }

    // --- central plaza: warm cobblestones + ring path ---
    c.save();
    c.beginPath();
    const p0 = px(-10.5), p1 = px(10.5);
    c.rect(p0, p0, p1 - p0, p1 - p0);
    c.clip();
    c.fillStyle = '#4a4453';
    c.fillRect(p0, p0, p1 - p0, p1 - p0);
    const stone = 21 / 26;
    for (let gy = 0; gy < 26; gy++) {
      for (let gx = 0; gx < 26; gx++) {
        const shade = 58 + Math.floor(Math.random() * 26);
        c.fillStyle = `rgb(${shade + 14}, ${shade + 6}, ${shade - 4})`;
        const jx = (gx + (gy % 2 ? 0.5 : 0)) * stone - 10.5;
        const jz = gy * stone - 10.5;
        roundedRect(c, px(jx) + 1.5, px(jz) + 1.5, stone * S / 91 - 3, stone * S / 91 - 3, 4);
        c.fill();
      }
    }
    // ring path around the fountain
    c.strokeStyle = '#6b6272';
    c.lineWidth = S / 91 * 2.6;
    c.beginPath();
    c.arc(px(0), px(0), S / 91 * 5.6, 0, TAU);
    c.stroke();
    // soft center medallion
    c.fillStyle = 'rgba(120, 100, 130, 0.25)';
    c.beginPath();
    c.arc(px(0), px(0), S / 91 * 1.4, 0, TAU);
    c.fill();
    c.restore();

    // --- faint stains on asphalt for wear ---
    for (let i = 0; i < 26; i++) {
      const onStreet = Math.random() < 0.5;
      const x = onStreet ? pick(V_STREETS) + rand(-3, 3) : rand(-40, 40);
      const z = onStreet ? rand(-40, 40) : pick(H_STREETS) + rand(-3, 3);
      c.fillStyle = `rgba(0,0,0,${rand(0.03, 0.09)})`;
      c.beginPath();
      c.ellipse(px(x), px(z), rand(1, 4) * S / 91, rand(0.6, 2.4) * S / 91, rand(0, TAU), 0, TAU);
      c.fill();
    }
  });
}

function buildBase() {
  const base = new THREE.Group();

  const slab = new THREE.Mesh(
    new THREE.BoxGeometry(90, 4.6, 90),
    new THREE.MeshStandardMaterial({ color: 0x241c33, roughness: 0.95 })
  );
  slab.position.y = -2.3;
  base.add(slab);

  const rim = new THREE.Mesh(
    new THREE.BoxGeometry(92.4, 1.1, 92.4),
    new THREE.MeshStandardMaterial({ color: 0x171226, roughness: 1 })
  );
  rim.position.y = -4.55;
  base.add(rim);

  // soft glow beneath the island
  const glowTex = canvasTexture(256, 256, (c) => {
    const g = c.createRadialGradient(128, 128, 10, 128, 128, 128);
    g.addColorStop(0, 'rgba(122, 96, 190, 0.5)');
    g.addColorStop(0.55, 'rgba(90, 66, 140, 0.18)');
    g.addColorStop(1, 'rgba(0, 0, 0, 0)');
    c.fillStyle = g;
    c.fillRect(0, 0, 256, 256);
  });
  const glow = new THREE.Sprite(new THREE.SpriteMaterial({
    map: glowTex, transparent: true, depthWrite: false, opacity: 0.8,
  }));
  glow.scale.set(130, 130, 1);
  glow.position.y = -6.5;
  base.add(glow);

  scene.add(base);
}

function buildGround() {
  buildBase();
  TEX.streets = buildStreetTexture();
  const ground = new THREE.Mesh(
    new THREE.PlaneGeometry(91, 91),
    new THREE.MeshStandardMaterial({ map: TEX.streets, roughness: 0.94, metalness: 0.02 })
  );
  ground.rotation.x = -Math.PI / 2;
  ground.receiveShadow = true;
  scene.add(ground);
}

