+398   // cornice
+399   c.fillStyle = spec.trim;
+400   c.fillRect(0, 0, W, corniceH * s);
+401   c.fillStyle = 'rgba(0,0,0,0.25)';
+402   c.fillRect(0, corniceH * s, W, 2);
+403 
+404   // upper windows
+405   const cols = Math.max(2, Math.round(wM / 2.6));
+406   const winW = 0.95, winH = 1.2;
+407   for (let i = 0; i < spec.floors; i++) {
+408     const yC = groundH + (i + 0.55) * floorH;
