+418   // ground floor
+419   if (face.isFront && spec.ground === 'shop') {
+420     drawStorefront(c, W, s, spec, groundH);
+421   } else {
+422     // plain wall band + optional door / windows
+423     c.fillStyle = shade(spec.wall, -10);
+424     c.fillRect(0, top(groundH), W, groundH * s);
+425     c.fillStyle = spec.trim;
+426     c.fillRect(0, top(groundH), W, 0.12 * s);
