+532   c.arc(dx + dw - 8, top(1.5), 3, 0, TAU);
+533   c.fill();
+534   // kick band
+535   c.fillStyle = spec.trim;
+536   c.fillRect(gx0 - 4, top(glassBot), W - gx0 * 2 + 8, (glassBot - 0.35) * s);
