+701   const c = new THREE.Color(hex);
+702   const hsl = { h: 0, s: 0, l: 0 };
+703   c.getHSL(hsl);
+704   c.setHSL(hsl.h, hsl.s, clamp(hsl.l + amt / 255, 0, 1));
+705   return '#' + c.getHexString();
+706 }
