+const WALL_PALETTES = [
+  { wall: '#c9a97e', trim: '#8a6a4a', roof: '#5a4636' }, // warm sand
+  { wall: '#b0765c', trim: '#7c4a38', roof: '#4e3630' }, // terracotta
