+  { wall: '#a86a52', trim: '#75463a', roof: '#463029' }, // brick red
+  { wall: '#8f7d6b', trim: '#64564a', roof: '#3f352d' }, // taupe
+  { wall: '#b58a8f', trim: '#82606a', roof: '#4e3a40' }, // dusty rose
