  // cars wrap inside the world
  let inBounds = true;
  for (const c of state.cars) {
    const p = c.axis === 'x' ? c.group.position.x : c.group.position.z;
    if (p < -44 || p > 44) { inBounds = false; ok('car in bounds ' + c.kind, false, p); }
  }
  ok('cars in bounds', inBounds, null);

  // cars actually advanced along their axis
  const advanced = state.cars.every((c) => c.pos !== undefined && Number.isFinite(c.pos));
  ok('car positions finite', advanced, null);

  // pedestrians stay on their loops
  let pedOk = true;
  for (const p of state.people) {
    const d = p.t % p.perim;
    if (d < 0 || d >= p.perim) pedOk = false;
  }
  ok('pedestrian params in [0,perim)', pedOk, null);
  const ped = state.people[0];
  ok('pedestrian near plaza loop', Math.abs(Math.abs(ped.group.position.x) - 8.8) < 0.01 ||
    Math.abs(Math.abs(ped.group.position.z) - 8.8) < 0.01, ped.group.position.toArray());

  // buildings fit inside their blocks (no overflow into streets).
  // Measure the body box only: rotated props (e.g. pyramid roofs) make
  // Box3.setFromObject overestimate via AABB corner rotation.
  const box = new THREE.Box3();
  const inInt = (a, b) => (a >= -40.6 && b <= -19.4) || (a >= -10.6 && b <= 10.6) || (a >= 19.4 && b <= 40.6);
  let bCount = 0, bOk = true;
  for (const o of scene.children) {
    if (!o.userData.building) continue;
    bCount++;
    const body = o.children.find((ch) => ch.isMesh && ch.geometry.type === 'BoxGeometry');
    box.setFromObject(body);
    if (!inInt(box.min.x, box.max.x) || !inInt(box.min.z, box.max.z)) {
      bOk = false;
      ok('building fits block', false, box.min.toArray().map(Number).concat(box.max.toArray()));
      break;
    }
  }
  ok('buildings fit in blocks', bOk && bCount === 21, { bCount, bOk });

  // audio graph exists after a start attempt
  const snap = window.__city.snapshot();
  ok('audio state exposed', typeof snap.audio.started === 'boolean', snap.audio);

  // camera sane
  const dist = Math.hypot(...snap.camera.pos);
  ok('camera distance sane', dist > 10 && dist < 200, dist);

  console.log(out.pass ? 'SELFTEST PASS' : 'SELFTEST FAIL', JSON.stringify(out, null, 2));
  return out;
};

